from cloud_common import *  # noqa: F401,F403
R = 'f7-cloud'
T = []

# ---------------------------------------------------------------- 585 GitOps
T.append(topic(585, 'gitops-reconciliation', R, 15, 'GitOps: Pull-Based Delivery and Reconciliation',
 ['Describe Git as the declared desired state and an in-cluster agent as the deployer',
  'Explain how continuous reconciliation detects and reverts drift',
  'Promote changes between environments and roll back safely, including data'],
 2, 12, [322, 323, 325],
 [text(585, 1, 'Git holds the desired state',
   'In GitOps the declared configuration of each environment, such as deployments, services and policies, lives in a Git repository. Changes arrive as reviewed pull requests, so the history of production is the history of the repository. An agent running next to the system reads that repository and makes the live state match it, again and again, instead of a pipeline running commands once.',
   ['gitops-model']),
  diagram(585, 2, 'The reconcile loop', 'The agent compares two states on every cycle, not just when someone merges.', ['reconciliation'],
   ['A pull request changes the image tag in the config repository and is merged',
    'The agent notices the new commit, by polling or through a webhook',
    'It renders the manifests and compares them with the live state',
    'It applies only the differences and waits for the workloads to become healthy',
    'It reports whether each app is in sync, then repeats the comparison on an interval']),
  text(585, 3, 'Push vs pull: where the credentials live',
   'In a push pipeline, CI holds credentials for every cluster and runs the deploy commands, so a compromised CI system can change production. In a pull setup, CI only builds images and updates the config repository; the agent inside each cluster holds the cluster credentials and pulls. The cluster never has to accept inbound connections from CI.',
   ['gitops-model']),
  text(585, 4, 'Worked example: a hand-made hotfix disappears',
   'During an incident an engineer scales a deployment from 10 to 20 replicas by hand. A few minutes later it is back at 10: the agent saw that the live state had drifted from Git and reverted it. The fix is to make the change as a commit, or to pause self-heal for that app during the incident and record why. Drift reports also reveal hand-made changes that nobody wrote down.',
   ['drift']),
  text(585, 5, 'Trap: a git revert is a full rollback',
   'Reverting a commit restores the old manifests and the old image, but not the database. If the release ran a migration that dropped a column, the old code may fail against the new schema. Keep migrations backwards-compatible: add first, switch the code, drop later. That way a manifest revert really is safe.',
   ['gitops-rollback'])],
 [mc('t585-a1', 'gitops-model', 'In a pull-based GitOps setup, which component needs credentials that can change the production cluster?',
   [('a', 'The CI pipeline that builds and tests the images'),
    ('b', 'The agent running inside the production cluster'),
    ('c', 'Every developer who can merge to the config repository'),
    ('d', 'The container registry that stores the built images')], 'b',
   'Only the in-cluster agent applies changes. CI writes images and commits, developers change Git through reviewed merges, and the registry only stores images.'),
  mc('t585-a2', 'drift', 'An engineer edits a live deployment by hand while self-heal is on. What happens?',
   [('a', 'The edit stays until someone commits a matching change'),
    ('b', 'The agent commits the hand-made change back into Git'),
    ('c', 'The cluster rejects the edit because Git owns the object'),
    ('d', 'The agent reverts it to the Git version on its next sync')], 'd',
   'With self-heal, live state that differs from Git is drift and is put back. Agents do not write manual edits into Git, and the cluster API itself accepts the edit; the agent undoes it afterwards.'),
  mc('t585-a3', 'reconciliation', 'Git has not changed for a week, yet the agent keeps comparing live state with Git every few minutes. Why?',
   [('a', 'To find and correct drift from changes made outside Git'),
    ('b', 'To rebuild container images from the newest source code'),
    ('c', 'To renew the certificates that the cluster nodes use'),
    ('d', 'To stop its connection to the repository timing out')], 'a',
   'Reconciliation runs on an interval so hand edits, deleted objects and failed applies are noticed. Building images is CI’s job, certificate renewal is separate, and keeping a connection alive needs no full comparison.'),
  mc('t585-a4', 'gitops-rollback', 'A release ran a migration that dropped a column. You git-revert the release commit. What is still broken?',
   [('a', 'Nothing, because the revert restores the earlier state of the whole system'),
    ('b', 'The schema: the old code expects a column that the revert did not restore'),
    ('c', 'The image tag, because Git cannot revert changes to tags'),
    ('d', 'The agent, which stops syncing after a revert commit')], 'b',
   'Git versions the manifests, not the data. Image tags in manifests revert normally, and agents sync revert commits like any other commit.'),
  order('t585-a5', 'reconciliation', 'Order one GitOps reconcile cycle after a merge.',
   ['Merge the change to the config repository', 'The agent sees the new commit', 'Compare the rendered manifests with live state', 'Apply only the differences', 'Report sync and health status'],
   ['s3', 's5', 's1', 's4', 's2'], 'Commit, detect, diff, apply, report, and then the loop starts again.'),
  tradeoff('t585-a6', 'gitops-model', 'A team must deploy the same app to five clusters, staging first and then production.',
   ['Production changes need review', 'Security wants no cluster credentials in CI', 'Every change must be auditable'],
   [('p2', 'CI runs the deploy commands against each cluster with stored admin credentials', 'Push from CI'),
    ('p3', 'An engineer applies the manifests from a laptop after testing', 'Manual apply'),
    ('p1', 'A folder per environment in Git; promotion is a reviewed PR; an agent in each cluster pulls', 'GitOps promotion')], 'p1',
   [('r1', 'Cluster credentials stay inside the clusters'), ('r3', 'CI credentials are safe because the CI system is private'),
    ('r2', 'Every production change is a reviewed commit with history'), ('r4', 'A laptop apply is the easiest way to audit who changed what')],
   ['r1', 'r2'], ['r3', 'r4'],
   {'r3': 'Private CI systems still get compromised, and then they hold the keys to every cluster.',
    'r4': 'Laptop applies leave no reviewed record and depend on one person’s local setup.'},
   'Pull-based promotion keeps credentials in the clusters and makes the repository the audit log.')],
 flash(585, [('GitOps in one line?', 'Git holds the desired state; an agent in the cluster pulls it and reconciles continuously.'),
             ('What is drift?', 'Live state that differs from Git, for example a hand-made edit; self-heal reverts it.'),
             ('Why is a revert not a full rollback?', 'Git restores manifests, not data; schema changes must be backwards-compatible.')]),
 src([('Microsoft Learn: GitOps for Azure Kubernetes Service', 'https://learn.microsoft.com/en-us/azure/architecture/example-scenario/gitops-aks/gitops-blueprint-aks'),
      ('Google Cloud: Config Sync overview', 'https://cloud.google.com/kubernetes-engine/enterprise/config-sync/docs/overview'),
      ('AWS Prescriptive Guidance: GitOps tools for Amazon EKS', 'https://docs.aws.amazon.com/prescriptive-guidance/latest/eks-gitops-tools/introduction.html')]),
 deep(['gitops-model', 'reconciliation', 'drift', 'gitops-rollback'], 'How a GitOps agent keeps clusters in line with Git',
  ['GitOps rests on four ideas: the desired state is declarative, it is versioned and immutable in Git, an agent pulls it automatically, and the agent reconciles continuously. The repository becomes the single place to read what should be running, and its commit history doubles as the deployment log, with author, reviewer and time for every change.',
   'The agent runs in or next to each cluster. On each cycle it fetches the repository, renders templates or overlays into plain manifests, and asks the cluster for the live objects. It computes the difference, applies only what changed, waits for health checks, and records the result as in sync, out of sync or degraded. Webhooks make it react quickly to merges; the interval loop catches everything else.',
   'Drift is any difference that did not come from Git: a hand-scaled deployment, a deleted service, a config edited during an incident. With self-heal on, the agent puts it back; with self-heal off, it reports the drift and waits. Either way the team learns about changes that would otherwise surprise the next deploy. Fields that a controller owns, such as replica counts set by an autoscaler, should be excluded so the agent and the autoscaler do not fight.',
   'Promotion between environments is a change to Git. Common layouts keep a folder or overlay per environment and promote by updating the image digest in the next folder through a pull request, often opened by CI after tests pass. Long-lived branches per environment tend to drift apart and make merges painful. Secrets do not go into the repository in plain text; store references to a secret manager or encrypted values that only the cluster can decrypt.',
   'Rollback is a revert commit, which the agent applies like any change. That covers code and configuration but not data. Database migrations should follow expand and contract: add new columns or tables, deploy code that uses them, and remove old ones only in a later release. Then any single release can be reverted without breaking the schema it runs against.'],
  ['Teams running several clusters or environments that need audited, reviewed changes.', 'Platforms that want deploy credentials kept out of CI.'],
  ['Avoid for one small service where a simple pipeline is enough and adds less machinery.', 'Avoid managing fast-changing runtime values, such as autoscaled replica counts, in Git.'],
  ['Approach', 'Credentials', 'Drift handling'],
  [['Push from CI', 'CI holds cluster credentials', 'None between deploys'],
   ['GitOps, self-heal on', 'Agent in the cluster', 'Reverted by the agent'],
   ['GitOps, self-heal off', 'Agent in the cluster', 'Reported, fixed by a commit']],
  'How long drift survives',
  ['Reconcile interval of 3 minutes', 'Self-heal on', 'A hand edit made at a random moment', 'Illustrative interval; tools let you choose it'],
  ['The edit lands somewhere inside a 3-minute interval, on average halfway through.',
   'Average time until the next comparison: 3 ÷ 2 = 1.5 minutes; worst case 3 minutes.',
   'After that cycle the edit is reverted, so manual changes last minutes at most.'],
  'With a short interval and self-heal on, live state cannot stay different from Git for long, which is why incident changes must go through Git or a deliberate pause.',
  'Cloud providers’ GitOps guidance', 'Official documentation',
  'Microsoft’s architecture guide for GitOps on Azure Kubernetes Service describes a pull-based setup where an in-cluster operator reconciles cluster state with a Git repository. Google Cloud’s Config Sync overview describes syncing clusters from a Git repository and detecting and correcting drift, and AWS prescriptive guidance compares GitOps tools for Amazon EKS. All three treat Git as the source of truth and the agent as the deployer.',
  [('“GitOps means we run deploy commands from a Git hook.”', '“GitOps means an agent in the cluster pulls the declared state from Git and keeps reconciling it.”'),
   ('“If a release goes wrong we just revert the commit.”', '“Reverting restores manifests; I’d keep migrations expand-and-contract so the revert also works against the schema.”')],
  ['Git holds the desired state; an in-cluster agent pulls and applies it.', 'Reconciliation runs on an interval, so drift is found and reverted.', 'Promotion is a reviewed commit per environment, with credentials kept in the clusters.', 'A revert restores manifests, not data; keep schema changes backwards-compatible.']),
 predict('The agent goes down',
  'The GitOps agent in a production cluster crashes and stays down for an hour. During that hour two pull requests are merged into the config repository.',
  [('a', 'Running apps keep serving; the two merges are not deployed until the agent is back',
    'Right: the agent only applies changes. The workloads it deployed keep running without it.'),
   ('b', 'Every app in the cluster stops, because nothing is reconciling it',
    'Workloads are run by the cluster itself; the agent only changes what should run.'),
   ('c', 'CI notices the agent is down and pushes the merges directly',
    'In a pull setup CI has no cluster credentials, so it cannot push.')], 'a',
  'Alert on the agent’s health and on apps that stay out of sync, so a stuck agent is noticed before someone wonders why a fix never shipped.'),
 see([(323, 'The build-once pipeline that produces the images GitOps deploys'), (325, 'Declarative infrastructure, the same idea applied to cloud resources'), (324, 'Canary rollouts that a GitOps agent can drive step by step')])))

# ---------------------------------------------------------------- 586 chaos engineering
T.append(topic(586, 'chaos-engineering-game-days', R, 16, 'Chaos Engineering and Game Days',
 ['Write a chaos experiment as a steady-state hypothesis with a measured result',
  'Limit blast radius and define abort conditions before injecting a fault',
  'Run a game day that tests people, runbooks and access as well as systems'],
 3, 13, [326, 327],
 [text(586, 1, 'An experiment, not random breakage',
   'Chaos engineering is running controlled experiments to learn how a system behaves under failure. Pick a steady state you can measure, such as checkout success rate and p99 latency. State a hypothesis that it holds when a fault happens. Inject the fault into a small, controlled part of the system, compare it with a control group, and either gain confidence or find a weakness to fix.',
   ['steady-state-hypothesis']),
  diagram(586, 2, 'Running one experiment', 'Safety checks come before the fault, not after.', ['steady-state-hypothesis', 'abort-conditions'],
   ['Define steady state with metrics that users feel',
    'Write the hypothesis and the abort conditions',
    'Limit the scope: one zone, a small share of traffic, a fixed time',
    'Inject the fault and watch the steady-state metrics',
    'Stop at once if an abort condition fires; otherwise end on schedule',
    'Record what was learned and file the fixes']),
  text(586, 3, 'Worked example: losing a cache node',
   'Hypothesis: if one of three cache nodes is terminated, checkout success stays at or above 99.9% and p99 below 400 ms. Scope: one zone, 5% of traffic, 15 minutes. Abort: success below 99.5% for 2 minutes. Result (illustrative): success held, but p99 rose to 2 s because clients had no timeout on cache calls and waited on the dead node. The fix was a 50 ms cache timeout with a fallback to the database.',
   ['blast-radius', 'abort-conditions']),
  text(586, 4, 'Game days rehearse the people too',
   'A game day is a scheduled exercise where a team practises a realistic failure together: a zone loss, an expired certificate, a bad deploy. Beyond the system’s behaviour it tests whether alerts fire and reach the right person, whether dashboards answer the questions asked, whether the runbook still matches reality, and whether on-call has the access the runbook assumes. Observers write findings down as they happen.',
   ['game-days']),
  text(586, 5, 'Trap: starting with production and the whole fleet',
   'An experiment with no scope limit and no stop button is an outage you chose to cause. Start in a test environment, then move to production with a small blast radius once monitoring and an abort switch are proven. Widen the scope step by step, and avoid peak hours and active incidents.',
   ['blast-radius'])],
 [mc('t586-a1', 'steady-state-hypothesis', 'Which is a well-formed chaos hypothesis?',
   [('a', 'Killing a cache node in production will show us which parts break'),
    ('b', 'With one of three cache nodes gone, checkout success stays at 99.9% or more'),
    ('c', 'The system will keep working through any failure we can think of'),
    ('d', 'Terminating random servers every hour will make the whole team more careful')], 'b',
   'A hypothesis names a fault and a measurable steady state that should hold. “Show us what breaks” has no success criterion, “any failure” cannot be tested, and team behaviour is not a hypothesis about the system.'),
  mc('t586-a2', 'abort-conditions', 'During an experiment the error rate crosses the agreed abort threshold. What should happen?',
   [('a', 'Keep going to gather more data, and roll back when the window ends'),
    ('b', 'Widen the blast radius to confirm that the result is real'),
    ('c', 'Stop injecting the fault, restore normal service, then analyse'),
    ('d', 'Raise the threshold a little so the experiment can finish')], 'c',
   'Abort conditions exist to protect users; when one fires, stop and recover first. Continuing, widening or moving the threshold turns an experiment into an incident.'),
  mc('t586-a3', 'blast-radius', 'What is a sensible first production experiment for a new chaos programme?',
   [('a', 'Add 200 ms of latency to one dependency for 1% of traffic, with an abort switch'),
    ('b', 'Shut down a whole region during peak hours to test failover end to end'),
    ('c', 'Terminate half of the database replicas at once to test the quorum'),
    ('d', 'Inject faults into every service at once to find all the weak spots together')], 'a',
   'Start small, reversible and observable. A region shutdown at peak or half the replicas at once risks a real outage, and faults everywhere at once make it impossible to tell which fault caused what.'),
  mc('t586-a4', 'game-days', 'Which finding is a game day better at surfacing than an automated fault-injection run?',
   [('a', 'p99 latency rises when a dependency slows down'),
    ('b', 'A retry loop multiplies load during an outage'),
    ('c', 'A health check misses a hung process'),
    ('d', 'A runbook step needs access nobody on call has')], 'd',
   'Missing access is about people and process, which only shows up when humans run the response. The other three are system behaviours that automated experiments measure well.'),
  order('t586-a5', 'steady-state-hypothesis', 'Order the steps of a chaos experiment.',
   ['Define the steady-state metrics', 'Write the hypothesis and abort conditions', 'Limit the scope and schedule it', 'Inject the fault and observe', 'Record findings and file fixes'],
   ['s2', 's4', 's1', 's5', 's3'], 'Measure normal first, decide what success and failure look like, limit the risk, then inject and learn.'),
  est('t586-a6', 'blast-radius', 'A service handles 5,000 requests per second. An experiment affects 2% of traffic for 10 minutes. If every affected request failed, how many failures is that at most?', 'requests', 60000,
   ['Traffic is steady', 'Worst case: every affected request fails'], '5,000 × 0.02 × 600 s', '100 per second × 600 s = 60,000 requests',
   'Sanity check: against the 3,000,000 requests in those 10 minutes that is 2%, which is why scope and an abort rule should be agreed with the error budget in mind.', 0.05, [3000000, 6000])],
 flash(586, [('Chaos experiment parts?', 'Steady state, hypothesis, scoped fault, abort conditions, findings.'),
             ('Blast radius?', 'How much traffic, how many hosts and how long an experiment can affect.'),
             ('What does a game day test beyond the system?', 'Alerts, paging, dashboards, runbooks and on-call access.')]),
 src([('AWS Fault Injection Service: What is it?', 'https://docs.aws.amazon.com/fis/latest/userguide/what-is.html'),
      ('Microsoft Learn: What is Azure Chaos Studio?', 'https://learn.microsoft.com/en-us/azure/chaos-studio/chaos-studio-overview'),
      ('AWS Well-Architected: Test reliability', 'https://docs.aws.amazon.com/wellarchitected/latest/reliability-pillar/test-reliability.html'),
      ('Google SRE book: Testing for Reliability', 'https://sre.google/sre-book/testing-reliability/')]),
 deep(['steady-state-hypothesis', 'blast-radius', 'abort-conditions', 'game-days'], 'How a safe chaos programme works',
  ['Start from steady state: a small set of metrics that describe the system working for users, such as request success rate, p99 latency and orders per minute. Internal signals like CPU are useful context but are not the hypothesis, because users do not feel CPU. If you cannot measure steady state reliably, you are not ready to inject faults.',
   'Write the hypothesis before the experiment: under this fault, these metrics stay within these bounds. Faults come from real incidents and known risks: an instance or zone lost, a dependency slowed or returning errors, a full disk, clock skew, a certificate expiring, a DNS failure. Running the experiment against a control group, the same traffic without the fault, separates the fault’s effect from normal noise.',
   'Blast radius is the share of traffic, hosts and time that can be affected. Start with a test environment, then a small slice of production: one zone, one percent of requests, fifteen minutes. Define abort conditions, usually the same steady-state metrics with a hard limit, and wire them to stop the fault without waiting for a human. Managed fault-injection services support stop conditions tied to alarms for this reason.',
   'Most experiments find something: a missing timeout, a retry storm, an alert that never fired, a fallback that was never deployed. Each finding becomes a tracked fix, and the experiment is rerun after the fix to confirm it. Over time, passing experiments move into regular scheduled runs so regressions are caught, much like tests in a pipeline.',
   'Game days add people to the experiment. A facilitator runs a realistic scenario while the on-call team responds with their normal tools. Observers note where alerts were late, dashboards were missing, runbooks were wrong or access was missing. The result is a list of fixes to systems and processes, and a team that has practised the response before a real incident demands it.'],
  ['Services with SLOs, monitoring and on-call, where unknown failure behaviour is the main risk.', 'Before launches, migrations and region or zone changes.'],
  ['Avoid while steady state cannot be measured or there is no reliable way to stop the fault.', 'Avoid during active incidents, change freezes or peak events.'],
  ['Exercise', 'Finds', 'Cost'],
  [['Automated fault injection', 'System behaviour under one fault', 'Low once set up'],
   ['Game day', 'People, runbooks, access and alerts', 'A team’s afternoon'],
   ['Production incident', 'Everything, at the worst moment', 'Users and trust']],
  'Fitting an experiment inside the error budget',
  ['99.9% SLO over 30 days on 5,000 requests per second', 'Experiment: 2% of traffic for 10 minutes', 'Worst case: every affected request fails'],
  ['Monthly requests: 5,000 × 2,592,000 ≈ 13 billion; error budget 0.1% ≈ 13 million.',
   'Worst-case experiment cost: 5,000 × 0.02 = 100 affected requests per second, and 100 × 600 s = 60,000 failed requests.',
   '60,000 ÷ 13,000,000 ≈ 0.5% of the monthly budget, even if everything goes wrong.'],
  'A tightly scoped experiment with an abort rule risks a sliver of the error budget, far less than finding the same weakness in a real incident.',
  'Chaos at Netflix and in managed services', 'Publicly reported',
  'Netflix publicly described Chaos Monkey, a tool that randomly terminated production instances during business hours so engineers built services that survive instance loss, and later open-sourced it. Cloud providers now offer managed fault injection: AWS Fault Injection Service and Azure Chaos Studio both let teams define experiments with targets, actions and stop conditions tied to alarms, so an experiment halts when a metric crosses a limit.',
  [('“Chaos engineering means breaking production at random.”', '“It is a scoped experiment with a hypothesis and abort conditions, starting small and widening as confidence grows.”'),
   ('“Our failover works; we tested it once two years ago.”', '“I’d run it as a regular game day, because systems, runbooks and people change.”')],
  ['Write a hypothesis about user-facing steady-state metrics.', 'Limit blast radius and wire abort conditions before injecting.', 'Turn every finding into a tracked fix and rerun the experiment.', 'Game days test alerts, runbooks and access, not only the system.']),
 predict('The cache node experiment',
  'You terminate one of three cache nodes for 5% of traffic. The hypothesis was success ≥ 99.9% and p99 < 400 ms. Checkout success stays at 99.95%, but p99 latency jumps from 300 ms to 2 s. No alert fires.',
  [('a', 'The hypothesis failed on latency, and the missing alert is a second finding',
    'Right: one steady-state metric broke its bound, and nobody would have been paged for it.'),
   ('b', 'The experiment passed, because the success rate stayed above 99.9%',
    'The hypothesis covered p99 too; success alone hides a slow, frustrating checkout.'),
   ('c', 'The experiment was invalid, because the latency spike came from the experiment',
    'Showing the effect of the fault is the point of the experiment.')], 'a',
  'Add a short timeout with a fallback on cache calls, add a latency alert for checkout p99, and rerun the same experiment to confirm both fixes.'),
 see([(327, 'How the response is run when a real failure happens'), (326, 'Error budgets that bound how much risk an experiment may take'), (581, 'The zone-loss scenario many game days start with')])))
